<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {invoke} from '@tauri-apps/api/core'
import {executeQuery} from '@/lib/database'
import {useI18n} from '@/lib/i18n'
import {useDialogKeyboard} from '@/composables/useDialogKeyboard'
const {pick}=useI18n()
type Item={id:string;sku:string;name:string;pack_size:number;reorder_level:number;updated_at:string}
const products=ref<Item[]>([]),categories=ref<Array<{id:string;name:string}>>([]),query=ref(''),chosen=ref<string[]>([]),category=ref('_keep'),reorder=ref<number|string>(''),pack=ref<number|string>(''),busy=ref(false),error=ref(''),notice=ref(''),confirm=ref(false),dialog=ref<HTMLElement|null>(null),page=ref(0),pending=ref<any>(null)
useDialogKeyboard(dialog,()=>{if(!busy.value)confirm.value=false})
const productById=computed(()=>new Map(products.value.map(p=>[p.id,p])))
const visible=computed(()=>products.value.filter(p=>`${p.name} ${p.sku}`.toLowerCase().includes(query.value.toLowerCase()))),paged=computed(()=>visible.value.slice(page.value*100,(page.value+1)*100))
onMounted(load)
async function load(){busy.value=true;error.value='';try{[products.value,categories.value]=await Promise.all([executeQuery<Item>('SELECT id,sku,name,pack_size,reorder_level,updated_at FROM products WHERE deleted_at IS NULL ORDER BY name'),executeQuery<{id:string;name:string}>('SELECT id,name FROM categories WHERE is_active=1 AND deleted_at IS NULL ORDER BY name')]);chosen.value=[]}catch(e){error.value=String(e)}finally{busy.value=false}}
function review(){error.value='';notice.value='';if(!chosen.value.length||chosen.value.length>500||category.value==='_keep'&&reorder.value===''&&pack.value===''){error.value=pick('Choose 1–500 products and at least one change.','۱–۵۰۰ مصنوعات اور کم از کم ایک تبدیلی منتخب کریں۔');return}pending.value={requestId:crypto.randomUUID(),products:products.value.filter(p=>chosen.value.includes(p.id)).map(p=>({id:p.id,updatedAt:p.updated_at})),category:category.value==='_keep'?null:category.value,reorderLevel:reorder.value===''?null:Number(reorder.value),packSize:pack.value===''?null:Number(pack.value)};confirm.value=true}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const r=await invoke<{products:number}>('bulk_update_catalog',{request:pending.value});confirm.value=false;await load();notice.value=pick('Reviewed changes saved for','جانچی گئی تبدیلیاں محفوظ ہوئیں')+' '+r.products;pending.value=null}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><div class="tool-terminal documents-terminal"><header class="tool-header"><div><h1>{{pick('Bulk Catalog Setup','فہرست کی اجتماعی ترتیب')}}</h1><p>{{pick('Selected products only · no stock or price changes','صرف منتخب مصنوعات · اسٹاک یا قیمت میں تبدیلی نہیں')}}</p></div><button :disabled="busy" @click="load">{{pick('Reload','دوبارہ لوڈ')}}</button></header><form class="commercial-filters" @submit.prevent="review"><input v-model="query" type="search" :placeholder="pick('Name / SKU','نام / SKU')" @input="page=0"/><label>{{pick('Category','قسم')}}<select v-model="category"><option value="_keep">{{pick('Keep category','موجودہ قسم برقرار')}}</option><option value="">{{pick('Clear category','قسم خالی کریں')}}</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>{{pick('Reorder level','دوبارہ آرڈر کی حد')}}<input v-model="reorder" type="number" min="0" max="100000000" step="1" :placeholder="pick('Blank = keep','خالی = برقرار')"/></label><label>{{pick('Pack size','پیک سائز')}}<input v-model="pack" type="number" min="1" max="100000" step="1" :placeholder="pick('Blank = keep','خالی = برقرار')"/></label><button class="bg-primary" :disabled="busy">{{pick('Review changes','تبدیلیوں کا جائزہ')}}</button></form><p class="commercial-hint">{{pick('Pack size can change only for unused products with no batches or transaction history. Category/reorder changes preserve prices and stock. Concurrent catalog edits block the entire batch; reload and review again.','پیک سائز صرف بغیر بیچ اور بغیر لین دین والی مصنوعات میں بدل سکتا ہے۔ قسم / آرڈر کی حد بدلنے سے قیمت اور اسٹاک برقرار رہتے ہیں۔ بیک وقت تبدیلی پر مکمل عمل روکا جاتا ہے؛ دوبارہ لوڈ کر کے جائزہ لیں۔')}}</p><p v-if="error" role="alert" class="commercial-error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><div class="commercial-table-scroll"><table><thead><tr><th>{{pick('Select','منتخب')}}</th><th>SKU</th><th>{{pick('Name','نام')}}</th><th>{{pick('Pack','پیک')}}</th><th>{{pick('Reorder','آرڈر حد')}}</th></tr></thead><tbody><tr v-for="p in paged" :key="p.id"><td><input v-model="chosen" type="checkbox" :value="p.id" :disabled="busy" :aria-label="p.name"/></td><td>{{p.sku}}</td><td>{{p.name}}</td><td>{{p.pack_size}}</td><td>{{p.reorder_level}}</td></tr></tbody></table></div><footer class="tool-summary"><strong>{{chosen.length}} {{pick('selected','منتخب')}}</strong><button :disabled="!page" @click="page--">{{pick('Previous','پچھلا')}}</button><button :disabled="(page+1)*100>=visible.length" @click="page++">{{pick('Next','اگلا')}}</button></footer><div v-if="confirm" class="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4"><form ref="dialog" class="commercial-dialog" role="dialog" aria-modal="true" tabindex="-1" @submit.prevent="save"><h2>{{pick('Confirm selected catalog changes','منتخب فہرست کی تبدیلیوں کی تصدیق')}}</h2><p>{{pending.products.length}} {{pick('products','مصنوعات')}}</p><ul style="max-height:140px;overflow:auto"><li v-for="p in pending.products" :key="p.id">{{productById.get(p.id)?.sku}} · {{productById.get(p.id)?.name}}</li></ul><p>{{pick('Category','قسم')}}: {{pending.category===null?pick('Keep','برقرار'):pending.category===''?pick('Clear','خالی'):categories.find(c=>c.id===pending.category)?.name}} · {{pick('Reorder','آرڈر حد')}}: {{pending.reorderLevel??pick('Keep','برقرار')}} · {{pick('Pack','پیک')}}: {{pending.packSize??pick('Keep','برقرار')}}</p><p v-if="error" class="commercial-error" role="alert">{{error}}</p><div><button type="button" :disabled="busy" @click="confirm=false">{{pick('Cancel','منسوخ')}}</button> <button class="bg-primary" :disabled="busy">{{pick('Save reviewed changes','جانچی گئی تبدیلیاں محفوظ کریں')}}</button></div></form></div></div></template>
